const landing=document.querySelector('#landing');
function showLanding(){document.body.classList.add('landing-active');history.replaceState(null,'','#welcome');window.scrollTo(0,0)}
document.querySelectorAll('[data-enter]').forEach(button=>button.addEventListener('click',()=>{document.body.classList.remove('landing-active');let profile;try{profile=JSON.parse(localStorage.getItem('nqtaProfileV2'))}catch{}if(profile&&tracks[profile.track]&&Array.isArray(profile.subjects)){launchApp(profile)}else{document.querySelector('#onboarding').hidden=false;document.body.classList.add('onboarding-active');syncSetup()}window.scrollTo(0,0)}));
const returnButton=document.createElement('button');returnButton.id='returnLanding';returnButton.textContent='Retour à l’accueil';returnButton.addEventListener('click',showLanding);document.querySelector('.onboarding-top').append(returnButton);
const appReturn=returnButton.cloneNode(true);appReturn.removeAttribute('id');appReturn.className='text-btn';appReturn.addEventListener('click',showLanding);document.querySelector('.side-bottom').prepend(appReturn);
const navDescriptions=['Votre point de départ','Votre temps de travail','Vos matières','Sujets officiels','Votre progression','Votre note cible'];document.querySelectorAll('.nav-copy small').forEach((el,index)=>el.textContent=navDescriptions[index]);document.querySelector('.nav-goal .nav-copy b').textContent='Objectif Bac';document.querySelector('.profile-orbit b').textContent='N';document.querySelector('.avatar').textContent='N';document.querySelector('.nav-intro span').textContent='2e BAC · MAROC';
let demoAnswer=null;
function renderPreview(index,scroll=false){document.querySelectorAll('.l-tabs [data-preview]').forEach((button,i)=>{button.setAttribute('aria-selected',String(i===index));button.tabIndex=i===index?0:-1});const panel=document.querySelector('#demoPanel');const header='<span class="l-demo-tag"><span>LE DÉCLIC / MATHÉMATIQUES</span><span>APERÇU</span></span>';const content=[`<h3>Une fonction, c’est une transformation.</h3><p>On entre un nombre. Une règle le transforme. On obtient un résultat.</p><span class="l-equation">x → 2x + 1</span><p>Avec 3 au départ : 2 × 3 + 1 = <b>7</b>.</p>`,`<h3>À toi. Si x = 4,<br>combien vaut 2x + 1 ?</h3><div class="l-answer-row"><button data-answer="8">8</button><button data-answer="9">9</button><button data-answer="10">10</button></div><p class="l-feedback" id="demoFeedback">Choisis une réponse pour voir l’explication.</p>`,`<h3>${demoAnswer==='9'?'Le lien est fait.':'Un petit essai. Un point de départ.'}</h3><ul class="l-demo-list"><li><span>01</span>Identifier la règle</li><li><span>02</span>Remplacer x par sa valeur</li><li><span>03</span>Calculer, puis vérifier</li></ul><p>Cette démonstration ne crée aucune note dans ton espace.</p>`];panel.innerHTML=header+content[index];panel.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>{demoAnswer=button.dataset.answer;panel.querySelectorAll('[data-answer]').forEach(b=>b.classList.toggle('chosen',b===button));document.querySelector('#demoFeedback').textContent=demoAnswer==='9'?'Exact : 2 × 4 + 1 = 9. La multiplication se fait avant l’addition.':'Reprends dans l’ordre : 2 × 4 = 8, puis ajoute 1. Le résultat est 9.'}));if(scroll)document.querySelector('#apercu').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
document.querySelectorAll('[data-preview]').forEach(button=>button.addEventListener('click',()=>renderPreview(Number(button.dataset.preview),button.classList.contains('l-card'))));document.querySelector('.l-tabs').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('.l-tabs button')];let index=tabs.indexOf(document.activeElement);index=event.key==='Home'?0:event.key==='End'?2:(index+(event.key==='ArrowRight'?1:2))%3;renderPreview(index);tabs[index].focus()});
renderPreview(0);showLanding();
